class CustomerEnricher : IMutateIncomingMessages {
    readonly ICustomerSource source;
    public CustomerEnricher(ICustomerSource source) => this.source = source;

    public async Task MutateIncoming(MutateIncomingMessageContext context) {
        var order = (OrderPlaced)context.Message;
        order.CustomerName = await source.NameOfAsync(order.CustomerId);
        context.Message = order;      // pipeline continues with the enriched instance
    }
}
