record Order(string CustomerId, string? CustomerName = null, string? Region = null);

async Task<Order> EnrichAsync(Order order, CancellationToken ct) {
    var c = await cache.GetOrCreateAsync(order.CustomerId, async e => {
        e.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
        return await customers.GetAsync(order.CustomerId, ct);   // typed HttpClient
    });
    return c is null ? order : order with { CustomerName = c.Name, Region = c.Region };
}
